// Defensive normalizer: AIGEN bounties may arrive as JSON or HTML.
const input = $input.first().json;
const body = input.body ?? input;

let raw = '';
if (typeof body === 'string') raw = body;
else if (body && typeof body === 'object') raw = JSON.stringify(body);

// JSON path
let list = [];
if (body && typeof body === 'object') {
  const cand = body.data ?? body.bounties ?? body.items ?? body.results;
  if (Array.isArray(cand)) list = cand;
  else if (Array.isArray(body)) list = body;
}

// HTML path: pull link+title pairs out of the DOM text.
if (list.length === 0 && /<a/i.test(raw)) {
  const re = /<a[^>]*href=["']([^"']+)["'][^>]*>([^<]{5,120})<\/a>/gi;
  let m;
  while ((m = re.exec(raw)) && list.length < 50) {
    const href = m[1];
    if (/javascript:|mailto:|^#/.test(href)) continue;
    list.push({ url: href, title: m[2].replace(/<[^>]+>/g, '').trim() });
  }
}

const bounties = list.map((b, i) => ({
  title: b.title ?? b.name ?? `Bounty ${i + 1}`,
  url: b.url ?? b.link ?? '',
  reward: b.reward ?? b.payout ?? b.bounty ?? null,
  status: b.status ?? b.state ?? 'open',
  platform: 'aigen'
})).slice(0, 30);

return [{
  json: {
    userId: $json.userId ?? null,
    timestamp: new Date().toISOString(),
    bounties,
    count: bounties.length
  }
}];

